function translate(value: string, language: Language): string {
  if (language === "EN") return value;
  const trimmed = value.trim();
  const languageTranslations = translations[language];
  const localized = languageTranslations[value] ?? languageTranslations[trimmed];
  return localized ? value.replace(trimmed, localized) : value;
}

function localizeNode(node: React.ReactNode, language: Language): React.ReactNode {
  if (typeof node === "string") return translate(node, language);
  if (Array.isArray(node)) return node.map((child) => localizeNode(child, language));
  if (!isValidElement(node)) return node;

  const props: Record<string, unknown> = {};
  const element = node as React.ReactElement<Record<string, unknown>>;
  for (const key of ["placeholder", "aria-label", "title", "alt"]) {
    const value = element.props[key];
    if (typeof value === "string") props[key] = translate(value, language);
  }
  props.children = Children.map(element.props.children as React.ReactNode, (child) => localizeNode(child, language));
  return cloneElement(node, props);
}

type LanguageContextValue = {
  currentLanguage: Language;
  setCurrentLanguage: (language: Language) => void;
  t: (text: string) => string;
  translations: typeof translations;
};

const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [currentLanguage, setCurrentLanguage] = useState<Language>(() => {
    const savedLanguage = window.localStorage.getItem("velora-language");
    return savedLanguage === "HU" || savedLanguage === "SK" ? savedLanguage : "EN";
  });

  useEffect(() => {
    window.localStorage.setItem("velora-language", currentLanguage);
    document.documentElement.lang = currentLanguage.toLowerCase();
  }, [currentLanguage]);

  const t = (text: string) => translate(text, currentLanguage);
  return (
    <LanguageContext.Provider value={{ currentLanguage, setCurrentLanguage, t, translations }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used within a LanguageProvider");
  return context;
}

export function Localize({ children }: { children: React.ReactNode }) {
  const { currentLanguage } = useLanguage();
  return <>{localizeNode(children, currentLanguage)}</>;
}
